pub fn mock_router(
    models: &[(&str, &str)],
    request_count: usize,
) -> (String, std::thread::JoinHandle<Vec<String>>) {
    let listener = TcpListener::bind("127.0.0.1:0").expect("bind mock catalog");
    listener
        .set_nonblocking(true)
        .expect("make mock catalog nonblocking");
    let port = listener.local_addr().expect("listener address").port();
    let body = serde_json::json!({
        "object": "list",
        "data": models
            .iter()
            .map(|(id, owner)| serde_json::json!({"id": id, "owned_by": owner}))
            .collect::<Vec<_>>()
    })
    .to_string();
    let server = std::thread::spawn(move || {
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        let mut requests = Vec::new();
        while requests.len() < request_count {
            let mut stream = loop {
                match listener.accept() {
                    Ok((stream, _)) => break stream,
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        if std::time::Instant::now() >= deadline {
                            return requests;
                        }
                        std::thread::sleep(Duration::from_millis(10));
                    }
                    Err(error) => panic!("accept mock router request: {error}"),
                }
            };
            stream
                .set_nonblocking(false)
                .expect("make mock router connection blocking");
            stream
                .set_read_timeout(Some(Duration::from_secs(5)))
                .expect("set timeout");
            let mut bytes = Vec::new();
            let mut buffer = [0_u8; 4096];
            loop {
                let count = stream.read(&mut buffer).expect("read request");
                if count == 0 {
                    break;
                }
                bytes.extend_from_slice(&buffer[..count]);
                if bytes.windows(4).any(|window| window == b"\r\n\r\n") {
                    break;
                }
            }
            let request = String::from_utf8_lossy(&bytes).into_owned();
            let path = request
                .lines()
                .next()
                .and_then(|line| line.split_whitespace().nth(1))
                .unwrap_or("");
            let (status, response_body) = match path {
                "/api/health" => ("200 OK", r#"{"status":"ok","version":"test"}"#),
                "/api/management/tokens" => ("401 Unauthorized", r#"{"error":"ordinary token"}"#),
                _ if request.starts_with("GET ") => ("200 OK", body.as_str()),
                _ => ("200 OK", "{}"),
            };
            let response = format!(
                "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{response_body}",
                response_body.len()
            );
            stream
                .write_all(response.as_bytes())
                .expect("write mock router response");
            requests.push(request);
        }
        requests
    });
    (format!("http://127.0.0.1:{port}"), server)
}

pub fn mock_admin_router(
    models: &[(&str, &str)],
    client: &str,
    request_count: usize,
) -> (String, std::thread::JoinHandle<Vec<String>>) {
    let listener = TcpListener::bind("127.0.0.1:0").expect("bind mock admin router");
    listener
        .set_nonblocking(true)
        .expect("nonblocking admin router");
    let port = listener.local_addr().expect("admin router address").port();
    let catalog = serde_json::json!({
        "object": "list",
        "data": models
            .iter()
            .map(|(id, owner)| serde_json::json!({"id": id, "owned_by": owner}))
            .collect::<Vec<_>>()
    })
    .to_string();
    let token = bound_client_token(client, "repair-principal");
    let issued = serde_json::json!({"token": token}).to_string();
    let server = std::thread::spawn(move || {
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        let mut requests = Vec::new();
        while requests.len() < request_count {
            let mut stream = loop {
                match listener.accept() {
                    Ok((stream, _)) => break stream,
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        if std::time::Instant::now() >= deadline {
                            return requests;
                        }
                        std::thread::sleep(Duration::from_millis(10));
                    }
                    Err(error) => panic!("accept mock admin router request: {error}"),
                }
            };
            stream
                .set_nonblocking(false)
                .expect("make accepted admin connection blocking");
            let mut bytes = Vec::new();
            let mut buffer = [0_u8; 4096];
            loop {
                let count = stream.read(&mut buffer).expect("read admin request");
                if count == 0 {
                    break;
                }
                bytes.extend_from_slice(&buffer[..count]);
                if bytes.windows(4).any(|window| window == b"\r\n\r\n") {
                    break;
                }
            }
            let request = String::from_utf8_lossy(&bytes).into_owned();
            let path = request
                .lines()
                .next()
                .and_then(|line| line.split_whitespace().nth(1))
                .unwrap_or("");
            let (status, body) = match path {
                "/api/health" => ("200 OK", r#"{"status":"ok","version":"test"}"#),
                "/api/management/tokens" => ("200 OK", r#"{"data":[]}"#),
                "/api/management/tokens/client" => ("200 OK", issued.as_str()),
                "/api/management/tokens/revoke" => ("200 OK", r#"{"revoked":true}"#),
                _ if request.starts_with("GET ") => ("200 OK", catalog.as_str()),
                _ => ("404 Not Found", r#"{"error":"unexpected path"}"#),
            };
            write!(
                stream,
                "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            )
            .expect("write mock admin response");
            requests.push(request);
        }
        requests
    });
    (format!("http://127.0.0.1:{port}"), server)
}
